 const upload=async event=>{event.preventDefault();if(!files.length){setError('Choose one or more MP4 or WebM lectures first.');return}if(!draft.module.trim()){setError('Enter the chapter name for these videos.');return}if(!draft.rightsConfirmed){setError('Confirm that you have permission to share these videos.');return}const invalid=files.filter(file=>!(/\.(mp4|webm)$/i.test(file.name))||file.size>8589934592);if(invalid.length){setError(`${invalid.length} selected file${invalid.length===1?' is':'s are'} unsupported or larger than 8 GB. Remove them and retry.`);return}const collator=new Intl.Collator(undefined,{numeric:true,sensitivity:'base'});const ordered=[...files].sort((a,b)=>videoOrderFromFilename(a.name,Number.MAX_SAFE_INTEGER)-videoOrderFromFilename(b.name,Number.MAX_SAFE_INTEGER)||collator.compare(a.name,b.name));setBusy(true);setProgress(0);setError('');setNotice('');let completedBytes=0,uploaded=0,duplicates=0;const failed=[];try{for(let i=0;i<ordered.length;i++){const file=ordered[i];setUploadingName(`${file.name} · ${i+1} of ${ordered.length}`);const form=new FormData();form.append('file',file);form.append('title',ordered.length===1&&draft.title.trim()?draft.title.trim():videoTitleFromFilename(file.name));form.append('module',draft.module.trim());form.append('description',draft.description);form.append('attribution',draft.attribution);form.append('sortOrder',String(videoOrderFromFilename(file.name,Number(draft.sortOrder)+i)));form.append('publish',String(draft.publish));form.append('rightsConfirmed',String(draft.rightsConfirmed));try{await uploadRequest('/api/admin/media/videos',form,percent=>setProgress(Math.min(100,Math.round((completedBytes+file.size*percent/100)/Math.max(1,selectedBytes)*100))));uploaded++}catch(e){if(e.status===409)duplicates++;else failed.push(`${file.name}: ${e.message||'upload failed'}`)}completedBytes+=file.size;setProgress(Math.round(completedBytes/Math.max(1,selectedBytes)*100))}await refresh();setFiles([]);setUploadingName('');const input=document.getElementById('video-upload-files');if(input)input.value='';setDraft(current=>({...current,title:'',description:'',attribution:'',rightsConfirmed:false}));setNotice(`${uploaded} lecture${uploaded===1?'':'s'} added${duplicates?`; ${duplicates} duplicate${duplicates===1?' was':'s were'} skipped`:''}${failed.length?`; ${failed.length} failed`:''}.`);if(failed.length)setError(`Could not add: ${failed.slice(0,3).join(' · ')}${failed.length>3?' · See the remaining files and retry them':''}`)}finally{setBusy(false);setProgress(0)}};
