  <header className="video-hero"><div className="video-hero-copy"><div className="eyebrow"><span className="live-dot"/>{publicOnly?'PREPTRACK · LLD LECTURES':'YOUR LEARNING LIBRARY · LLD VIDEOS'}</div><h1>{publicOnly?'Learn the design.':'LLD, explained on screen.'}</h1><p>{publicOnly?'A read-only lecture library available inside your private Tailscale network.':'Your video files stay on the Windows SSD. Tailscale-connected learners can watch; only you can add or publish lectures.'}</p><div className="video-hero-meta"><span><Film size={14}/>{videos.length} {videos.length===1?'lecture':'lectures'}</span><span><ShieldCheck size={14}/>{publicOnly?'Available inside Tailscale':'Video bytes stay on your Windows laptop'}</span></div></div><div className="video-hero-orb"><span className="video-orbit video-orbit-a"/><span className="video-orbit video-orbit-b"/><span className="video-orb-icon"><Play size={27} fill="currentColor"/></span></div></header>
